+			run_id: input.runId,
+			step_name: "implementation:amendment",
+			phase: result.step.phase,
+			iteration: result.step.iteration,
+			result_json: JSON.stringify(result.step.result),
+			head_commit: result.approvedPlanCommit,
+		});
+	}
